import time
import pyautogui

pyautogui.FAILSAFE = True

REPORT = [
    "LAB ATTENDANCE SUMMARY",
    "======================",
    "Course      : Business Process Automation",
    "Class       : VII CSE - A",
    "Total       : 62",
    "Present     : 57",
    "Absent      : 5",
    f"Attendance  : {57 / 62 * 100:.2f} %",
    "Generated by: PyAutoGUI Desktop Bot",
]

print("Bot starts in 3 seconds. Do not use mouse/keyboard...")
time.sleep(3)

# 1. Open Notepad
pyautogui.hotkey("win", "r")
time.sleep(1)
pyautogui.write("notepad", interval=0.05)
pyautogui.press("enter")
time.sleep(2)

# 2. Type the report
for line in REPORT:
    pyautogui.write(line, interval=0.02)
    pyautogui.press("enter")
print("Report typed into Notepad")

# 3. Save the file
pyautogui.hotkey("ctrl", "s")
time.sleep(1.5)
pyautogui.write("attendance_report.txt", interval=0.03)
pyautogui.press("enter")
time.sleep(1)
print("File saved as attendance_report.txt")

# 4. Screenshot of the result
pyautogui.screenshot("notepad_output.png")
print(f"Screen size: {pyautogui.size()}")
print("Screenshot saved as notepad_output.png")
print("Desktop automation completed successfully!")
